create table agent_commitment (created_at timestamp(6), due_at timestamp(6), id bigint generated by default as identity, resolved_at timestamp(6), updated_at timestamp(6), status varchar(16) not null, evidence varchar(300), content varchar(500) not null, primary key (id));
create table agent_lesson (clean_reviews integer not null, difficulty float(53) not null, recurrence_count integer not null, stability float(53) not null, created_at timestamp(6) not null, first_seen_at timestamp(6) not null, id bigint generated by default as identity, last_review_at timestamp(6), last_seen_at timestamp(6) not null, next_review_at timestamp(6), updated_at timestamp(6), status varchar(16) not null, category varchar(24) not null, trigger_type varchar(24) not null, evidence varchar(300), correction varchar(500) not null, expected_result varchar(500) not null, what_happened varchar(500) not null, what_i_did varchar(500) not null, primary key (id));
create table agent_quest (note_count integer not null, retract_count integer not null, step_count integer not null, closed_at timestamp(6), created_at timestamp(6) not null, id bigint generated by default as identity, updated_at timestamp(6), status varchar(16) not null, title varchar(200) not null, evidence varchar(300), next_step varchar(600), why varchar(600) not null, primary key (id));
create table agent_quest_note (created_at timestamp(6) not null, id bigint generated by default as identity, quest_id bigint not null, retracted_at timestamp(6), evidence varchar(300), retract_reason varchar(300), source_title varchar(300), source_url varchar(1000), content varchar(2000) not null, primary key (id));
create table agent_quest_run (budget_yuan numeric(10,4) not null, completion_tokens integer not null, cost_yuan numeric(10,4) not null, duration_ms integer not null, extended boolean not null, note_count integer not null, prompt_tokens integer not null, retract_count integer not null, step_count integer not null, cache_hit_tokens bigint not null, cache_miss_tokens bigint not null, created_at timestamp(6) not null, id bigint generated by default as identity, quest_id bigint, status varchar(16) not null, reason varchar(500), summary varchar(2000), primary key (id));
create table agent_reflection (calls integer not null, completion_tokens integer not null, duration_ms integer not null, importance integer not null, level integer not null, prompt_chars integer not null, prompt_tokens integer not null, response_chars integer not null, created_at timestamp(6) not null, id bigint generated by default as identity, written_back bigint, trigger_type varchar(16), input_event_ids varchar(500), conclusion varchar(1000) not null, primary key (id));
create table agent_self_block (char_limit integer not null, version integer not null, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), block_type varchar(16) not null, label varchar(64) not null, description varchar(200), value varchar(4000), primary key (id), constraint uk_self_block unique (block_type, label));
create table agent_self_event (importance integer not null, created_at timestamp(6) not null, id bigint generated by default as identity, stance varchar(16), kind varchar(24) not null, topic varchar(60), evidence varchar(300), content varchar(1000) not null, primary key (id));
create table agent_self_utterance (created_at timestamp(6) not null, id bigint generated by default as identity, quest_id bigint, sent_at timestamp(6), status varchar(16) not null, evidence varchar(300), why varchar(500) not null, content varchar(1000) not null, primary key (id));
create table agent_stance (counter_count integer not null, difficulty float(53) not null, revise_count integer not null, stability float(53) not null, support_count integer not null, formed_at timestamp(6) not null, id bigint generated by default as identity, last_review_at timestamp(6), next_review_at timestamp(6), updated_at timestamp(6), direction varchar(16) not null, status varchar(16) not null, topic varchar(60) not null, counter_ids varchar(300), evidence_ids varchar(300), content varchar(600) not null, primary key (id));
create table conversation_memory (created_at timestamp(6), expires_at timestamp(6), id bigint generated by default as identity, role varchar(16) not null, event_key varchar(128), user_id varchar(128) not null, source_media_ids varchar(1000), source_message_ids varchar(2000), content varchar(32600) not null, primary key (id), constraint uq_conversation_user_event unique (user_id, event_key));
create table episodic_memory (confidence integer, importance integer, created_at timestamp(6), ended_at timestamp(6), id bigint generated by default as identity, last_confirmed_at timestamp(6), last_used_at timestamp(6), occurred_at timestamp(6), superseded_by_id bigint, updated_at timestamp(6), episode_type varchar(32) not null, source_type varchar(32) not null, status varchar(32) not null, user_id varchar(128) not null, title varchar(200) not null, keywords varchar(1000), source_media_ids varchar(1000), source_message_ids varchar(2000), summary varchar(32600) not null, primary key (id));
create table exam_checkin (checkin_date date not null, minutes integer, tasks_done integer, tasks_total integer, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), user_id varchar(128) not null, note varchar(500), primary key (id));
create table exam_milestone (due_date date, created_at timestamp(6), done_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), name varchar(120) not null, user_id varchar(128) not null, note varchar(300), primary key (id));
create table exam_mistake (correct_streak integer, next_review_date date, review_stage integer, created_at timestamp(6), id bigint generated by default as identity, last_reviewed_at timestamp(6), updated_at timestamp(6), status varchar(16), source varchar(60), subject varchar(60), subject_group varchar(60), user_id varchar(128) not null, title varchar(300) not null, detail varchar(1000), primary key (id));
create table exam_plan (daily_minutes integer, enabled boolean, exam_date date, last_evening_push date, last_morning_push date, last_weekly_push date, created_at timestamp(6), updated_at timestamp(6), stage varchar(16), major varchar(120), school varchar(120), user_id varchar(128) not null, remark varchar(500), subjects varchar(2000), primary key (user_id));
create table exam_progress (done integer, due_date date, total integer, created_at timestamp(6), id bigint generated by default as identity, last_touched_at timestamp(6), updated_at timestamp(6), phase varchar(16), unit varchar(16), subject varchar(60), subject_group varchar(60), user_id varchar(128) not null, title varchar(200) not null, note varchar(300), primary key (id));
create table exam_task (plan_date date not null, planned_minutes integer, sort_order integer, created_at timestamp(6), done_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), source varchar(16), status varchar(16), subject varchar(60), user_id varchar(128) not null, content varchar(300), note varchar(300), primary key (id));
create table interview_round (score_content integer, score_delivery integer, score_depth integer, score_structure integer, seq integer, created_at timestamp(6), id bigint generated by default as identity, category varchar(32), session_id varchar(40), role varchar(120), user_id varchar(128) not null, question varchar(600), feedback varchar(800), answer_summary varchar(1200), primary key (id));
create table maimemo_setting (updated_at timestamp(6), setting_key varchar(64) not null, setting_value varchar(2048), primary key (setting_key));
create table memory_archive (created_at timestamp(6), id bigint generated by default as identity, user_id varchar(128), original_ids varchar(2000), summary varchar(4000), primary key (id));
create table memory_change_log (created_at timestamp(6), id bigint generated by default as identity, target_id bigint, action varchar(32), layer varchar(32), operator varchar(32), user_id varchar(128), reason varchar(512), after_content varchar(4000), before_content varchar(4000), primary key (id));
create table memory_extraction_run (completion_tokens integer not null, cost_yuan numeric(10,4) not null, duration_ms integer not null, prompt_tokens integer not null, reasoning_tokens integer not null, window_chars integer not null, window_turns integer not null, cache_hit_tokens bigint not null, cache_miss_tokens bigint not null, created_at timestamp(6) not null, id bigint generated by default as identity, trigger_source varchar(32) not null, skip_reason varchar(64), user_id varchar(128) not null, verdict_json varchar(512), written_ids varchar(512), primary key (id));
create table operation_log (created_at timestamp(6), id bigint generated by default as identity, action varchar(64), user_id varchar(128), detail varchar(2000), primary key (id));
create table reminder_task (prewarm_minutes integer, created_at timestamp(6), id bigint generated by default as identity, trigger_at timestamp(6), updated_at timestamp(6), status varchar(32), cron varchar(64), user_id varchar(128), content varchar(2000), primary key (id));
create table scheduled_task (enabled boolean, run_count integer, created_at timestamp(6), id bigint generated by default as identity, last_run_at timestamp(6), next_run_at timestamp(6), updated_at timestamp(6), status varchar(16), cron varchar(64) not null, title varchar(120), user_id varchar(128) not null, last_error varchar(500), instruction varchar(2000), last_result varchar(2000), primary key (id));
create table stored_media (created_at timestamp(6), id bigint generated by default as identity, size_bytes bigint, trashed_at timestamp(6), updated_at timestamp(6), status varchar(16) not null, sha256 varchar(64) not null, content_type varchar(128), user_id varchar(128) not null, importance_reason varchar(1000), trash_reason varchar(1000), relative_path varchar(1024) not null, summary varchar(2000), source_url varchar(2048), extracted_text varchar(32600), file_name varchar(255) not null, original_name varchar(255), source_message_id varchar(255), primary key (id));
create table user_core_memory (confidence integer, importance integer, created_at timestamp(6), id bigint generated by default as identity, last_confirmed_at timestamp(6), last_decision_at timestamp(6), last_used_at timestamp(6), superseded_by_id bigint, updated_at timestamp(6), source_type varchar(32), status varchar(32), user_id varchar(128), keywords varchar(1000), source_media_ids varchar(1000), source_message_ids varchar(2000), content varchar(4000), primary key (id));
create table user_profile (memory_enabled boolean, proactive_care_enabled boolean, created_at timestamp(6), last_care_at timestamp(6), last_seen_at timestamp(6), next_care_at timestamp(6), updated_at timestamp(6), proactive_care_cadence varchar(16), coach_mode varchar(32), last_channel varchar(32), coach_session_id varchar(40), coach_role varchar(120), last_bot_id varchar(128), user_id varchar(128) not null, persona varchar(4000), primary key (user_id));
create table user_work_memory (archived boolean, confidence integer, importance integer, priority integer, created_at timestamp(6), id bigint generated by default as identity, last_confirmed_at timestamp(6), last_decision_at timestamp(6), last_used_at timestamp(6), superseded_by_id bigint, updated_at timestamp(6), valid_from timestamp(6), valid_until timestamp(6), source varchar(32), source_type varchar(32), status varchar(32), user_id varchar(128), keywords varchar(1000), source_media_ids varchar(1000), content varchar(2000), source_message_ids varchar(2000), primary key (id));
create index idx_self_commitment_status on agent_commitment (status, due_at);
create index idx_self_lesson_status on agent_lesson (status, next_review_at);
create index idx_self_lesson_category on agent_lesson (category, status, last_seen_at);
create index idx_self_quest_status on agent_quest (status, updated_at);
create index idx_self_quest_note_quest on agent_quest_note (quest_id, created_at);
create index idx_self_quest_note_recent on agent_quest_note (created_at, retracted_at);
create index idx_self_quest_run_created on agent_quest_run (created_at);
create index idx_self_reflection_level on agent_reflection (level, created_at);
create index idx_self_event_kind on agent_self_event (kind, created_at);
create index idx_self_event_topic on agent_self_event (topic, stance, created_at);
create index idx_self_utterance_status on agent_self_utterance (status, created_at);
create index idx_self_stance_status on agent_stance (status, next_review_at);
create index idx_self_stance_topic on agent_stance (topic, status);
create index idx_conversation_user_created on conversation_memory (user_id, created_at);
create index idx_conversation_expires on conversation_memory (expires_at);
create index idx_episode_user_occurred on episodic_memory (user_id, occurred_at);
create index idx_episode_user_status on episodic_memory (user_id, status);
create index idx_exam_milestone_user on exam_milestone (user_id, due_date);
create index idx_exam_mistake_user on exam_mistake (user_id, status, next_review_date);
create index idx_exam_mistake_group on exam_mistake (user_id, subject_group);
create index idx_exam_progress_user on exam_progress (user_id, subject_group);
create index idx_exam_progress_due on exam_progress (user_id, due_date);
create index idx_exam_task_user_date on exam_task (user_id, plan_date);
create index idx_exam_task_user_status on exam_task (user_id, status);
create index idx_interview_user_session on interview_round (user_id, session_id);
create index idx_archive_user on memory_archive (user_id);
create index idx_changelog_user on memory_change_log (user_id);
create index idx_mer_user_time on memory_extraction_run (user_id, created_at);
create index idx_oplog_user on operation_log (user_id);
create index idx_reminder_user on reminder_task (user_id);
create index idx_scheduled_user on scheduled_task (user_id);
create index idx_scheduled_enabled on scheduled_task (enabled);
create index idx_media_user_status on stored_media (user_id, status);
create index idx_media_user_hash on stored_media (user_id, sha256);
create index idx_core_user on user_core_memory (user_id);
create index idx_work_user on user_work_memory (user_id);
